observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_1ef2f09e331f343e>
    <urn:graphragprov:unit:u_821252abb5cecd3d>
    <urn:graphragprov:unit:u_b8a465dc7a0961d9>
    <urn:graphragprov:unit:u_b98646df80e2c75e>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
